#!/usr/bin/env bash
# Create the Windows 11 IoT Enterprise LTSC VM with the 3D (Venus) configuration already applied.
#   sudo bash scripts/create-vm.sh --windows-iso ~/Downloads/win11-ltsc.iso --virtio-iso ~/Downloads/virtio-win.iso
#   bash scripts/create-vm.sh --windows-iso x --virtio-iso y --dry-run     # print the final XML, define nothing (no root)
# Options: --name win11  --vcpus 8  --memory-gib 8  --disk-gib 160  --rendernode /dev/dri/renderD128
#
# The base VM is what a normal Windows 11 guest needs (UEFI, TPM 2.0 emulator, virtio disk/net, guest agent, SPICE), generated by
# virt-install and then rewritten by scripts/apply-3d.py (3D virtio-gpu, SPICE GL socket, fence-poll module path, no enrolled
# Secure Boot keys). virtio-win.iso: https://fedorapeople.org/groups/virt/virtio-win/direct-downloads/stable-virtio/virtio-win.iso
# The disk is virtio, so Windows setup needs the storage driver: "Load driver" -> virtio-win CD -> viostor\w11\amd64
# (docs/02-vm.md). The ISO of Windows is NOT included and must be obtained from Microsoft.
set -euo pipefail
NAME=win11; VCPUS=8; MEM=8; DISK=160; RENDER=/dev/dri/renderD128; WIN_ISO=; VIRTIO_ISO=; DRY=0
while (($#)); do case $1 in
  --windows-iso) WIN_ISO=$2; shift 2;; --virtio-iso) VIRTIO_ISO=$2; shift 2;; --name) NAME=$2; shift 2;;
  --vcpus) VCPUS=$2; shift 2;; --memory-gib) MEM=$2; shift 2;; --disk-gib) DISK=$2; shift 2;;
  --rendernode) RENDER=$2; shift 2;; --dry-run) DRY=1; shift;; *) echo "unknown option $1"; exit 1;; esac; done
[[ -n $WIN_ISO && -n $VIRTIO_ISO ]] || { sed -n 2,5p "$0"; exit 1; }
[[ $DRY -eq 1 || $EUID -eq 0 ]] || { echo "run with sudo (or add --dry-run)"; exit 1; }
[[ -r $WIN_ISO && -r $VIRTIO_ISO ]] || { echo "cannot read the ISO files"; exit 1; }
R=$(cd "$(dirname "$0")/.." && pwd); C=qemu:///system; IMG=/var/lib/libvirt/images
THREADS=2; CORES=$((VCPUS/THREADS)); ((CORES>=1)) || { CORES=1; THREADS=1; }

if [[ $DRY -eq 0 ]]; then
  virsh -c $C dominfo "$NAME" &>/dev/null && { echo "VM $NAME already exists"; exit 1; }
  [[ -n ${SUDO_USER:-} ]] && usermod -aG libvirt "$SUDO_USER"
  install -m 644 -o qemu -g qemu "$WIN_ISO"    "$IMG/$NAME-install.iso"
  install -m 644 -o qemu -g qemu "$VIRTIO_ISO" "$IMG/virtio-win.iso"
  WIN_ISO=$IMG/$NAME-install.iso; VIRTIO_ISO=$IMG/virtio-win.iso
  qemu-img create -f qcow2 "$IMG/$NAME.qcow2" "${DISK}G" >/dev/null
  chown qemu:qemu "$IMG/$NAME.qcow2"; chmod 600 "$IMG/$NAME.qcow2"
fi

SIZEOPT=; [[ -e $IMG/$NAME.qcow2 ]] || SIZEOPT=",size=$DISK"      # only a dry run has no disk file yet
XML=$(mktemp); trap 'rm -f "$XML" "$XML.3d"' EXIT
virt-install --connect $C --dry-run --print-xml \
  --name "$NAME" --osinfo win11 \
  --vcpus "$VCPUS,sockets=1,cores=$CORES,threads=$THREADS" --cpu host-passthrough \
  --memory "memory=$((MEM*1024)),currentMemory=$((MEM*1024))" \
  --memorybacking source.type=memfd,access.mode=shared \
  --boot uefi,cdrom,hd \
  --tpm backend.type=emulator,backend.version=2.0,model=tpm-crb \
  --disk "path=$IMG/$NAME.qcow2,format=qcow2,bus=virtio,discard=unmap,cache=writeback$SIZEOPT" \
  --disk path="$WIN_ISO",device=cdrom,bus=sata \
  --disk path="$VIRTIO_ISO",device=cdrom,bus=sata \
  --network network=default,model=virtio \
  --channel unix,target.type=virtio,target.name=org.qemu.guest_agent.0 \
  --graphics spice --video virtio --channel spicevmc --sound ich9 \
  > "$XML"
python3 -I "$R/scripts/apply-3d.py" "$XML" -o "$XML.3d" --rendernode "$RENDER"

if [[ $DRY -eq 1 ]]; then cat "$XML.3d"; exit 0; fi
bash "$R/scripts/qemu-fence-patch.sh"
virsh -c $C define "$XML.3d"
cat <<EOF
VM '$NAME' defined (${VCPUS} vCPUs, ${MEM} GiB, ${DISK} GiB disk, 3D configured).
Next: virsh -c $C start $NAME && virt-viewer -c $C --attach $NAME   (then docs/02-vm.md: install Windows, then docs/03-guest.md)
EOF
